# install-unified-design.ps1
# Unified visual language rollout; dropped "overdue days" shaming language;
# customer screens relationship-first; fixed unstable 3-1-2 pick order
# (CSV-imported contacts sharing identical created_at broke the sort
# tiebreaker); fixed a crash from a missing showReferralOptions state;
# and reworked the "1 meeting" pick so it follows the PPT's actual 3-1-2
# definition (3->1: schedule a meeting with someone you have been actively
# interacting with) instead of being gated purely by manual stage tags with
# no regard for recent contact. ASCII-only script body (all Chinese text is
# base64), so it can't be corrupted by a non-UTF8 console.
#
# Usage:
#   1) Put this file in the project root (next to package.json).
#   2) Run: .\install-unified-design.ps1
#   It writes the files into src\pages, runs git add/commit/push, then
#   deletes itself.

$ErrorActionPreference = 'Stop'
$target = Join-Path (Get-Location) 'src\pages'

if (!(Test-Path $target)) {
    Write-Host "ERROR: src\pages not found. Run this from the project root (next to package.json)." -ForegroundColor Red
    exit 1
}

$utf8NoBom = New-Object System.Text.UTF8Encoding $false

function Write-Base64File($b64, $destPath) {
    $clean = $b64 -replace '\s', ''
    $bytes = [System.Convert]::FromBase64String($clean)
    [System.IO.File]::WriteAllBytes($destPath, $bytes)
}

function Decode-Base64Text($b64) {
    $clean = $b64 -replace '\s', ''
    $bytes = [System.Convert]::FromBase64String($clean)
    return $utf8NoBom.GetString($bytes)
}

